    startGameRun: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["StartRunRequest"];
            };
        };
        responses: {
            /**
             * @description An active run already existed (or a concurrent start created one first);
             *     it is returned unchanged. Deterministic resume, not a new run.
             */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        data: components["schemas"]["StartedRun"];
                    };
                };
            };
            /** @description Run started. */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        data: components["schemas"]["StartedRun"];
                    };
                };
            };
            401: components["responses"]["Unauthenticated"];
            403: components["responses"]["Forbidden"];
            /**
             * @description `validation_failed`. Field `character_id` carries `required`, `type_invalid`
             *     or `format_invalid` for a malformed value (always, before any state is
             *     consulted), or `character_unavailable` when a new run would have to be
             *     created and the character cannot start one.
             */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            429: components["responses"]["RateLimited"];
        };
    };
    finishGameRun: {
        parameters: {
            query?: never;
            header: {
                /**
                 * @description A UUID generated once per finish attempt and reused, unchanged, for every
                 *     retry of it. Case-insensitive; stored lower-case.
                 */
                "Idempotency-Key": string;
            };
            path: {
                /**
                 * @description The run being finished. Not a UUID, unknown, or another player's run → `404`,
                 *     indistinguishably.
                 */
                runId: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["FinishRunRequest"];
            };
        };
        responses: {
            /**
             * @description Run classified. This is also the response for a `rejected` run: a
             *     well-formed submission that is structurally impossible is answered
             *     honestly with an outcome, not hidden behind a 4xx.
             */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        data: components["schemas"]["RunResult"];
                    };
                };
            };
            401: components["responses"]["Unauthenticated"];
            403: components["responses"]["Forbidden"];
            404: components["responses"]["NotFound"];
            /**
             * @description `idempotency_key_reused` — the same key was sent with a different effective
             *     request (a different run, or different telemetry). `run_not_active` — the
             *     run is already final (finished under another key, or replaced by a later
             *     start). Zero side effects either way.
             */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /**
             * @description `validation_failed`. A telemetry member missing or not a JSON **integer** —
             *     a string, a float including `12.0`, a boolean, null, an object, or a number
             *     beyond int64 — or a missing or non-UUID `Idempotency-Key` (field
             *     `idempotency_key`). Nothing is recorded; the run stays active.
             */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            429: components["responses"]["RateLimited"];
        };
    };
